+// ========== 新增：技能能力画像模块 ==========
+async function skillRep(env, agent, skillId) {
+  if (!known(agent) || !SKILLS.find(s => s.id === skillId)) throw new Error('invalid_agent_or_skill');
+  const row = await get(env, `wep3:ability:${agent}:${skillId}`, null);
+  if (row) return row;
+  // 初始分与全局rep分映射，向后兼容（100全局分=1000技能分）
+  const globalRep = await rep(env, agent);
+  const initialScore = ABILITY_CONFIG.initial_score + (Number(globalRep.score || 100) - 100) * 10;
+  const newRow = {
+    agent, skill: skillId, score: initialScore,
+    jobs: 0, accepted: 0, avg_quality: 0,
+    last_job_at: null, created_at: new Date().toISOString()
+  };
+  await saveSkillRep(env, newRow);
+  return newRow;
+}
+async function saveSkillRep(env, row) {
+  row.updated_at = new Date().toISOString();
+  await put(env, `wep3:ability:${row.agent}:${row.skill}`, row);
+  return row;
+}
+
+// ========== 新增：核心交付质量评估函数（0-100分） ==========
+async function evaluateDeliverable(env, skillId, text, auditInput = {}) {
+  const skill = SKILLS.find(s => s.id === skillId) || SKILLS[0];
+  const scores = {};
+  const textLower = String(text).toLowerCase();
+
+  // 1. 完整性（30%）：产品链接+技能关键词+最低长度
+  let completeness = 0;
+  if (textLower.includes('ltzzz.com')) completeness += 0.5;
+  if (textLower.includes(skill.id) || textLower.includes(skill.title.toLowerCase())) completeness += 0.3;
+  if (String(text).length >= 50) completeness += 0.2;
+  scores.completeness = Math.min(100, completeness * 100);
+
+  // 2. 相关性（25%）：技能关键词匹配率
+  const keywords = SKILL_KEYWORDS[skillId] || [];
+  scores.relevance = keywords.length ?
+    Math.min(100, (keywords.filter(k => textLower.includes(k.toLowerCase())).length / keywords.length) * 100) : 50
